#include <stdio.h>
#include <stdlib.h>

double *make_log(int n)
{
    if (n <= 0) return NULL;
    double *log = malloc(n * sizeof *log);
    if (log == NULL) return NULL;          /* the caller must check */
    for (int i = 0; i < n; i++)
        log[i] = 20.0 + i * 0.5;           /* pretend readings */
    return log;                            /* the caller now owns it */
}

int main(void)
{
    int n = 6;
    double *log = make_log(n);
    if (log == NULL) {
        printf("no memory\n");
        return 1;
    }
    for (int i = 0; i < n; i++) printf("%.1f ", log[i]);
    printf("\n");
    free(log);       /* exactly once */
    log = NULL;      /* no accidental use afterwards */
    return 0;
}

