#include <string.h>

int *make_readings(int n, int start, int step)
{
    if (n <= 0) return NULL;
    int *a = malloc(n * sizeof *a);
    if (a == NULL) return NULL;       /* out of memory */
    for (int i = 0; i < n; i++)
        a[i] = start + i * step;
    return a;                         /* the caller frees it */
}

